import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../supabaseClient';
import PaymentModal from '../shared/PaymentModal';
import { formatPrivateName } from '../../utils/nameFormatter';
import { useAuth } from '../../context/AuthContext';

function Applications() {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [applications, setApplications] = useState([]);
  const [filter, setFilter] = useState('all'); // all, pending, accepted, rejected
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [selectedApplication, setSelectedApplication] = useState(null);
  const [message, setMessage] = useState('');

  const loadApplications = useCallback(async () => {
    if (!user?.id) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);

      // Get all applications for projects owned by this architect
      const { data, error } = await supabase
        .from('applications')
        .select(`
          *,
          project:project_id (
            id,
            title,
            budget,
            currency,
            deadline,
            architect_id
          ),
          artist:artist_id (
            id,
            full_name,
            profile_photo,
            location,
            bio,
            base_rate
          )
        `)
        .eq('project.architect_id', user.id)
        .order('created_at', { ascending: false });

      if (error) throw error;

      // Filter out applications where project is null (deleted projects)
      const validApplications = data.filter(app => app.project !== null);
      setApplications(validApplications);
    } catch (error) {
      console.error('Error loading applications:', error);
      setMessage('Error loading applications: ' + error.message);
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  useEffect(() => {
    if (user?.id) {
      loadApplications();
    } else {
      setLoading(false);
    }
  }, [user?.id, loadApplications]);

  const handleAccept = (application) => {
    setSelectedApplication(application);
    setShowPaymentModal(true);
  };

  const handleReject = async (applicationId) => {
    const reason = window.prompt('Reason for rejection (optional):');
    
    try {
      const { error } = await supabase
        .from('applications')
        .update({ 
          status: 'rejected',
          rejection_reason: reason || null
        })
        .eq('id', applicationId);

      if (error) throw error;

      setMessage('✅ Application rejected');
      await loadApplications();
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      console.error('Error rejecting application:', error);
      setMessage('❌ Error rejecting application');
    }
  };

  const handlePaymentSuccess = async () => {
    setShowPaymentModal(false);
    
    try {
      const { error } = await supabase
        .from('applications')
        .update({ status: 'accepted' })
        .eq('id', selectedApplication.id);

      if (error) throw error;

      setMessage('✅ Payment completed! Artist accepted successfully.');
      await loadApplications();
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      console.error('Error updating application:', error);
      setMessage('❌ Error updating status');
    }
  };

  const getStatusBadge = (status) => {
    const badges = {
      pending: { label: 'Pending', className: 'badge-pending', color: '🟡' },
      accepted: { label: 'Accepted', className: 'badge-accepted', color: '🟢' },
      rejected: { label: 'Rejected', className: 'badge-rejected', color: '🔴' }
    };
    return badges[status] || badges.pending;
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      day: '2-digit',
      month: 'short',
      year: 'numeric'
    });
  };

  const filteredApplications = applications.filter(app => {
    if (filter === 'all') return true;
    return app.status === filter;
  });

  const getFilterCounts = () => {
    return {
      all: applications.length,
      pending: applications.filter(a => a.status === 'pending').length,
      accepted: applications.filter(a => a.status === 'accepted').length,
      rejected: applications.filter(a => a.status === 'rejected').length
    };
  };

  const counts = getFilterCounts();

  if (loading) {
    return <div className="loading">Loading applications...</div>;
  }

  return (
    <div className="applications-container">
      <h2 className="section-title">Received Applications</h2>
      <p className="subtitle">
        All artist proposals for your projects
      </p>

      {message && (
        <div className={`message ${message.includes('✅') ? 'message-success' : 'message-error'}`}>
          {message}
        </div>
      )}

      {/* Filter Tabs */}
      <div className="filter-tabs">
        <button
          className={`filter-tab ${filter === 'all' ? 'active' : ''}`}
          onClick={() => setFilter('all')}
        >
          All ({counts.all})
        </button>
        <button
          className={`filter-tab ${filter === 'pending' ? 'active' : ''}`}
          onClick={() => setFilter('pending')}
        >
          Pending ({counts.pending})
        </button>
        <button
          className={`filter-tab ${filter === 'accepted' ? 'active' : ''}`}
          onClick={() => setFilter('accepted')}
        >
          Accepted ({counts.accepted})
        </button>
        <button
          className={`filter-tab ${filter === 'rejected' ? 'active' : ''}`}
          onClick={() => setFilter('rejected')}
        >
          Rejected ({counts.rejected})
        </button>
      </div>

      {filteredApplications.length === 0 ? (
        <div className="empty-state">
          <p className="empty-state-title">
            {filter === 'all'
              ? 'No applications received yet'
              : `No ${
                  filter === 'pending' ? 'pending' :
                  filter === 'accepted' ? 'accepted' : 'rejected'
                } applications`
            }
          </p>
          <p className="empty-state-text">
            Post projects to start receiving proposals from artists!
          </p>
        </div>
      ) : (
        <div className="applications-list">
          {filteredApplications.map(app => {
            const statusBadge = getStatusBadge(app.status);
            
            return (
              <div key={app.id} className="application-item">
                <div className="application-item-header">
                  <div className="artist-quick-info">
                    <div className="artist-photo-small">
                      {app.artist.profile_photo ? (
                        <img src={app.artist.profile_photo} alt={formatPrivateName(app.artist.full_name)} />
                      ) : (
                        <div className="photo-placeholder-small">
                          {formatPrivateName(app.artist.full_name)?.charAt(0)}
                        </div>
                      )}
                    </div>
                    <div>
                      <h3 className="artist-name-small">{formatPrivateName(app.artist.full_name)}</h3>
                      <p className="project-title-small">
                        For: <strong>{app.project.title}</strong>
                      </p>
                    </div>
                  </div>
                  <span className={`status-badge ${statusBadge.className}`}>
                    {statusBadge.color} {statusBadge.label}
                  </span>
                </div>

                <div className="application-item-body">
                  {app.artist.location && (
                    <p className="artist-location-small">📍 {app.artist.location}</p>
                  )}

                  <div className="application-details-compact">
                    <div className="detail-compact">
                      <span className="label">Price:</span>
                      <span className="value">R$ {app.quoted_price?.toFixed(2)}</span>
                    </div>
                    <div className="detail-compact">
                      <span className="label">Timeline:</span>
                      <span className="value">{app.delivery_timeline} days</span>
                    </div>
                    <div className="detail-compact">
                      <span className="label">Submitted:</span>
                      <span className="value">{formatDate(app.created_at)}</span>
                    </div>
                  </div>

                  <div className="proposal-preview">
                    <strong>Proposal:</strong>
                    <p>{app.proposal}</p>
                  </div>

                  {app.status === 'pending' && (
                    <div className="application-actions-inline">
                      <button
                        onClick={() => handleAccept(app)}
                        className="btn-primary btn-sm"
                      >
                        Accept
                      </button>
                      <button
                        onClick={() => handleReject(app.id)}
                        className="btn-secondary btn-sm"
                      >
                        Reject
                      </button>
                    </div>
                  )}

                  {app.status === 'accepted' && (
                    <div className="status-message success">
                      ✅ Artist accepted! The project is underway.
                    </div>
                  )}

                  {app.status === 'rejected' && app.rejection_reason && (
                    <div className="status-message error">
                      <strong>Reason for rejection:</strong>
                      <p>{app.rejection_reason}</p>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {showPaymentModal && selectedApplication && (
        <PaymentModal
          application={selectedApplication}
          onClose={() => setShowPaymentModal(false)}
          onSuccess={handlePaymentSuccess}
        />
      )}
    </div>
  );
}

export default Applications;